//! Protobuf messages of the Nocterm hub protocol, package `nocterm.hub.v2`.
//!
//! Owns: the generated `prost` messages, the encoded descriptor set and conversions between
//! wire enums and the neutral types of `nocterm-hub-model`.
//! Does not own: transport. gRPC stubs are generated by each transport crate from
//! [`FILE_DESCRIPTOR_SET`] with `extern_path(".nocterm.hub.v2", "::nocterm_hub_proto::v2")`,
//! so messages exist once and only transport crates depend on `tonic`.
//! Ports used/provided: none. Settings: none. Globals: none.
//! Invariants: within `v2`, fields and enum values are only added; a breaking change gets a
//! new package.

#[allow(
    clippy::all,
    clippy::pedantic,
    missing_debug_implementations,
    reason = "generated code"
)]
pub mod v2 {
    include!(concat!(env!("OUT_DIR"), "/nocterm.hub.v2.rs"));
}

mod convert;
mod hub_info;
mod redacted;

pub use convert::{assurance_from_wire, assurance_to_wire};
pub use hub_info::web_url_from_wire;

/// Encoded `FileDescriptorSet` of every `.proto` file, for code generation and reflection.
pub const FILE_DESCRIPTOR_SET: &[u8] =
    include_bytes!(concat!(env!("OUT_DIR"), "/hub_v2_descriptor.bin"));
